alter table public.training_app_versions
 add column if not exists initial_problem text,
 add column if not exists fix_summary text,
 add column if not exists verification_summary text;
begin;
update public.training_app_versions set initial_problem='Problem reports lacked reference numbers, assigned ownership, priority, and change history. Submitters needed status follow-up. Trainer response controls, live dashboard communications status, and certificate duration/preservation also needed updates.',fix_summary='Added ticket receipts, priority, ownership, status, required resolution summaries, history, stale-save protection, and My Reports. Added trainer acceptance/decline and Teams links. Dashboard reads live settings. Basic certificates show 4 Hours; existing certificates preserve their details without duplicate delivery. Updated the user manual.',verification_summary='TypeScript and production builds passed. Rollback database tests covered ticket creation, permissions, assignment, history, stale-save rejection, resolution, reopening, and reporter isolation. Live QA ticket BT-BUG-000012 was submitted, assigned, closed, and its resolution checked in My Reports. Trainer/database lifecycle and certificate tests passed; a separate trainer browser session was not exercised. Email receipt was confirmed. The guide and history were verified live.' where version='2.1.18';
update public.training_app_versions set initial_problem='The public form heading said Agency Trainer Contact Information rather than Agency Training Coordinator.',fix_summary='Renamed the section heading to Agency Training Coordinator while preserving its fields and submission behavior.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='2.1.17';
update public.training_app_versions set initial_problem='Basic Backtrace Search still displayed 1 Hour 30 Minutes and used a 90-minute base duration instead of the requested 4 Hours.',fix_summary='Updated the form and request duration calculations to 4 Hours / 240 minutes. Preserved completed 90-minute records as historical data.',verification_summary='Recorded verification: Promoted the verified v2.1.16 application build, kept the standalone Attendance deployment unchanged, and restored the staged-deployment auto-alias guard after postflight verification.' where version='2.1.16';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: users needed contextual application guidance and accessible tooltip controls.',fix_summary='Added contextual tooltips, keyboard and Escape controls, guide instructions, and viewport-safe tooltip positioning.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='2.1.15';
update public.training_app_versions set initial_problem='The Add Resource and Export CSV buttons were too close together.',fix_summary='Added a consistent 10-pixel gap, wrapping action layout, and full-width action group on narrow screens.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='2.1.14';
update public.training_app_versions set initial_problem='The retired standalone Attendance interface and paper import entry point were still served. A stale page-level version label and old routes caused inconsistent entry points.',fix_summary='Redirected retired Attendance and Tracker routes into the unified application, preserved query parameters, and removed the stale Attendance version label.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='2.1.13';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: grouped navigation needed clearer spacing, active-page cues, and a consistent presentation.',fix_summary='Refreshed grouped navigation popovers, spacing, rounded cards, active-page highlighting, and labels across the application.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='2.1.12';
update public.training_app_versions set initial_problem='The stored release record identifies accumulated administration/attendance stabilization issues and a final attendance close-window ordering correction; it does not describe every original symptom.',fix_summary='Completed the recorded stabilization work and close-window ordering correction, then locked the UAT-approved deployment and commit.',verification_summary='Recorded Final UAT verified attendance lifecycle, completion/archive behavior, certificate identity mapping, Resource Library share integrity, role gating, scheduled maintenance jobs, and production runtime health.' where version='2.1.11';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: System Status lacked a consolidated view of current, prior, and next releases and deployment lineage.',fix_summary='Added a read-only release lineage panel with current release, prior release, next development version, environment, and recent history.',verification_summary='Recorded verification: Qualified Preview dpl_55WKrf2kKgi2geowfzSjHtagrAWF and staging dpl_7yjSSbX2A5Ndcipq9Xz38AkBysQ3 as READY zero-alias artifacts with exact main/routing byte equality and zero AppDeploy dependencies.' where version='2.1.10';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: administrators needed one screen to inspect release version, communications state, queue, and production protections.',fix_summary='Added administrator-only System Status with version, architecture, communications, cron, queue, and protection visibility.',verification_summary='Recorded verification: Qualified Preview dpl_4gzo84cvjhyKv1tTH6PXn3zLi9cd and staging dpl_HmvrhgFX8NoFL5KqPhGZZ5NnUktq as READY, zero-alias artifacts with exact main and routing byte equality and zero AppDeploy dependencies.' where version='2.1.9';
update public.training_app_versions set initial_problem='Release tooling and routed modules still depended on AppDeploy; Email Settings needed its administrator-session bootstrap to run correctly through the application rewrite.',fix_summary='Moved release tooling, Version Tracker, resource modules, and Email Settings to GitHub/Vercel/Supabase and restored the Email Settings session bootstrap.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='2.1.8';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: controlled email templates, certificate delivery, and delivery-event infrastructure were needed.',fix_summary='Configured the verified sender, published ten email templates, added administrator test controls and certificate-email integration, and introduced delivery tracking infrastructure. Automatic delivery remained disabled at that release.',verification_summary='Recorded verification: Configured Backtrace Training <no-reply@training.gtbm.com> on the verified training.gtbm.com Resend domain. Credential testing passed. Automatic email delivery remains OFF with enabled_at null, preserving the historical backlog. Promoted v2.1.7 to exact Production deployment dpl_EQCvMj8RhafuSiAdoapk7Z6ga6iR. Post-promotion verification confirmed main Production READY, Attendance preserved at dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ, sender unchanged, automatic email delivery OFF, delivery tracking disabled, and the historical email backlog unchanged at 26 pending with 0 sent, 0 failed, and 0 historical rows rewritten/tagged.' where version='2.1.7';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: Resource Library placement and the unused More navigation group needed cleanup.',fix_summary='Moved Resource Library to the final primary-menu position and removed More while preserving routes and permissions.',verification_summary='Recorded verification: Exact approved Preview dpl_8p8UPGgHFFfpMRzgSnKrXg8SLTdb was staged as exact Production artifact dpl_DGcg7S1ULLF4DQdSpNc8mNaZGR5X. Staged validation confirmed exact Preview main bytes, exact routing bytes, all navigation-cleanup markers, required module health, and unchanged main/Attendance live aliases before promotion. Promoted exact staged artifact dpl_DGcg7S1ULLF4DQdSpNc8mNaZGR5X without rebuilding. Vercel promotion returned status 201. Resource Library, legacy Materials, Version Tracker, /version-history, /version-history/, main shell, /resources/, /materials/, Notifications, and Attendance smoke tests all passed; automatic rollback was not triggered. Signed-in live Production verification passed. Main Production is exact v2.1.6 deployment dpl_DGcg7S1ULLF4DQdSpNc8mNaZGR5X. Attendance remains exact v2.0.9 deployment dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ. No database schema changes were made.' where version='2.1.6';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: trainers needed a dedicated resource workflow with upload-driven organization and clear state/audience classification.',fix_summary='Expanded Training Materials into a top-level Resource Library with resource types, searchable state selection, audience classification, versioning, and optional metadata.',verification_summary='Recorded verification: Exact user-approved Preview dpl_HZmyenaFAyWkfZBo9bhCjLLU82Xr passed functional validation and was staged as exact Production artifact dpl_7VuRXgCLPKw4tNPcM1ooeAkfrDL7. The artifact was promoted without rebuilding; Resource Library, legacy /materials, Version Tracker, main shell, Notifications and Attendance smoke tests passed, automatic rollback was not triggered, and final signed-in Production verification passed.' where version='2.1.5';
update public.training_app_versions set initial_problem='The Training Manual menu label confused application instructions with Backtrace training content.',fix_summary='Renamed it App User Guide and moved it into Help, keeping the existing guide route and training resources separate.',verification_summary='Recorded verification: Promoted exact staged artifact dpl_49KrFsVnjDm47UWBkDh1jrXxoHUG without rebuilding. All guarded smoke tests passed, signed-in live Production verification passed, automatic rollback was not triggered, Attendance remains exact v2.0.9 deployment dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ, and no database/schema changes were required.' where version='2.1.4';
update public.training_app_versions set initial_problem='The recorded changes addressed inconsistent whitespace, email casing, agency terminology, and a canonical agency spelling while protecting historical certificate details.',fix_summary='Added field-aware input normalization in the interface and database, corrected the canonical agency and mutable directory record, and hardened internal helper access.',verification_summary='Recorded verification: Functionally verified exact Preview dpl_Bp2fmUAxRF7XgNr4ozkgxGE5uZZ4, then created exact staged Production artifact dpl_AKcBvt7CgrLr1ixAq6cSoagTdvk1 with autoAssignCustomDomains disabled. Staged validation confirmed exact Preview main bytes, exact Preview routing bytes, preserved v2.1.2 routing, all input-quality markers, Version Tracker health, and Attendance preservation. The exact staged artifact was promoted without rebuilding; Vercel returned 201 and all guarded smoke tests passed. Signed-in live Production verification passed after promotion. Main Production is exact v2.1.3 deployment dpl_AKcBvt7CgrLr1ixAq6cSoagTdvk1; Attendance remains exact v2.0.9 deployment dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ. Automatic rollback was not triggered.' where version='2.1.3';
update public.training_app_versions set initial_problem='Version Tracker used an invalid publishable-key Bearer flow and failed to load authenticated release history.',fix_summary='Changed Version Tracker to use the normal Supabase session and authenticated history RPC, preserving private history access.',verification_summary='Recorded verification: Functionally verified the exact Preview dpl_JBVZ1snFVSXqngkNyR2zB64TXcSU while signed in. Version Tracker loaded the protected release history successfully with no HTTP 401 and retained the Back to Training Administration navigation. Created staged Production artifact dpl_EfcX6YA58PCo1L9tnivVmVqKqd1R from the exact approved Preview with autoAssignCustomDomains disabled, validated exact Preview byte equivalence and preserved routing, then promoted that exact artifact without rebuilding. Post-promotion smoke tests passed for the main artifact, /version-history, /version-history/, /materials, /, /notifications, and /attendance. Independently verified the live Production Version Tracker while signed in after promotion. Main Production remains dpl_EfcX6YA58PCo1L9tnivVmVqKqd1R; Attendance remains exact v2.0.9 on dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ. No automatic rollback, database schema change, or Resend/email configuration change was required.' where version='2.1.2';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: flat navigation needed clearer role-aware groups and mobile navigation.',fix_summary='Grouped Training, People, and Administration, retained direct Dashboard/Notifications access, and added responsive navigation and active-route accessibility.',verification_summary='Recorded verification: Qualified Preview dpl_G2V9MhGqG72eBxkQTw9PWr5gXuuF, staged dpl_9vdhKgdERHspJwbFZ3wmCiXkd6Sd without live traffic, then promoted that exact artifact without rebuilding. Post-promotion smoke tests passed for the main artifact, /, /materials, /notifications, /attendance, and /version-history; Attendance remained on dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ and no runtime errors were observed after release.' where version='2.1.1';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: staff needed a product/jurisdiction-aware training library with version retention and secure student distribution. An initial routing candidate also failed the materials smoke test.',fix_summary='Added private, versioned training resources, class attachments, expiring student packets, large uploads, and distribution. Corrected trailing-slash materials routing after rollback.',verification_summary='Recorded verification: Qualified corrected Preview dpl_GYsfs9ybS7qjNxZot6cBuhh6XPxf and staged Production dpl_5ffFooFqtZirk2HximatDbjWUMLD. An earlier routing candidate failed the /materials smoke test and was automatically restored to v2.0.8; the corrected trailing-slash routing was then requalified. Promoted the exact corrected staged artifact without rebuilding, verified /materials, /, /notifications, /attendance, and /version-history at HTTP 200, preserved Attendance on dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ, and found no post-release runtime errors.' where version='2.1.0';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: paper sign-in sheets needed a reviewed, auditable attendance reconciliation workflow.',fix_summary='Added photo/image/PDF capture, private source retention, authenticated OCR, identity matching, and reviewed atomic attendance reconciliation. OCR did not issue certificates.',verification_summary='Recorded verification: Qualified Preview dpl_6aX1MoBsh7AfFjwZmMqyyS6fJs3q and staged Production dpl_GZj6JHKmZX1tZntc3ex8fXMmEXHQ. Promoted the exact staged artifact with rollback protection to dpl_Fo9qLCHDvo4kL49m61uHpJ5JW7xz. Verified HTTP 200 and paper-ingest markers on the live Attendance alias and main /attendance route, preserved main deployment dpl_FLn9UkYU8yPpmnAj9ghMiUcFb71M, and found no runtime errors after release.' where version='2.0.9';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: notification status, count-change feedback, keyboard focus, and current-page cues needed accessibility improvements.',fix_summary='Added live status semantics, dynamic unread labels, reduced-motion-aware count feedback, visible keyboard focus, and aria-current.',verification_summary='Recorded verification: Promoted deployment dpl_FLn9UkYU8yPpmnAj9ghMiUcFb71M and verified HTTP 200 for /, /notifications, /attendance, and /version-history. Confirmed the live production hostname resolves to the promoted deployment and found no runtime errors or warning/error logs after release.' where version='2.0.8';
update public.training_app_versions set initial_problem='Unread badge updates could wait for the 30-second refresh after a notification was marked read or unread.',fix_summary='Added immediate synchronization from the Notifications unread metric while retaining periodic, focus, visibility, and navigation refreshes.',verification_summary='Recorded verification: Verified production HTTP 200 for /, /notifications, /attendance, and /version-history; confirmed the live root serves all v2.0.7 observer markers; preserved Attendance class finalization and public certificate integration; and found no runtime errors after promotion.' where version='2.0.7';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: navigation needed a per-user unread count, zero-count hiding, and reliable refresh. The original source-clone deployment method also failed.',fix_summary='Added authenticated unread counts and refresh safeguards, then used a corrected preview/staged deployment workflow.',verification_summary='Recorded verification: Promoted the qualified staged Production artifact without rebuilding. Verified production HTTP 200 for /, /notifications, and /attendance; confirmed the live main shell contains all v2.0.6 notification markers; preserved Attendance certificate links and class-finalization workflow; and found no production runtime errors after release.' where version='2.0.6';
update public.training_app_versions set initial_problem='Closed classes awaiting finalization were not clearly identified and needed direct navigation to their completion record.',fix_summary='Added the Class Closed — Completion Required banner and a request-specific Finalize Training Record action.',verification_summary='Recorded verification: Preserved root / and /base routes, existing public certificate links, and verified the main tracker /attendance wrapper after production deployment.' where version='2.0.5';
update public.training_app_versions set initial_problem='Three remaining Attendance and Attendee Directory certificate links opened protected Vercel routes instead of the public certificate PDF.',fix_summary='Replaced the remaining links with the UUID-only Supabase certificate PDF endpoint.',verification_summary='Recorded verification: Deployed new production builds for Training Attendance and Attendee Directory, confirmed both deployments reached READY, verified the live pages retain required current functionality and contain the public certificate endpoint with no remaining protected certificate links, and confirmed no runtime errors were reported after deployment. Revalidated production certificate delivery after the frontend hotfix: UUID certificate retrieval returns HTTP 200 application/pdf with inline disposition and no-store headers, while sequential BTC-CERT numbers remain blocked from direct PDF retrieval with HTTP 400.' where version='2.0.4';
update public.training_app_versions set initial_problem='Certificate delivery used protected routes, sequential certificate numbers could expose full PDFs, and internal RPC, email, and dependency safeguards needed hardening.',fix_summary='Moved PDFs to UUID-only public retrieval, corrected email links, reduced RPC exposure, preserved activation-cutoff backlog safeguards, pinned the email processor dependency, and optimized request-insert RLS.',verification_summary='Recorded verification: Revalidated certificate verification by public UUID and certificate number, confirmed invalid identifiers return valid=false, and preserved the dedicated public verification site as the certificate verification destination referenced by issued PDFs. Hardened public certificate PDF retrieval so the full certificate document can be opened only with the high-entropy certificate_public_id UUID. Sequential BTC-CERT certificate numbers remain usable for the dedicated verification workflow but can no longer directly retrieve the PDF. Production QA confirmed UUID retrieval returns HTTP 200 application/pdf and sequential-number retrieval returns HTTP 400.' where version='2.0.3';
update public.training_app_versions set initial_problem='The Attendance parser exposed JavaScript/template code as page text. Related recorded fixes addressed redirect loops, legacy notification links, and production integrity/security gaps.',fix_summary='Sanitized malformed nested script boundaries and restored Attendance rendering/routing. Added the recorded authorization, payload, lifecycle, certificate, audit, scheduling, and retention safeguards detailed below.',verification_summary='Recorded verification: Validated the repaired Attendance /base endpoint with HTTP 200 and preserved the existing attendance, Badge/ID, class lifecycle, archive, print, Trainer Information, and certificate controls. Removed the obsolete public Badge # / ID # display while preserving certificate validity, participant, agency, training type/date, trainer, certificate number, request number, and issued date. Added database-level prevention of overlapping active classes for the same trainer. Rollback-only QA confirmed conflicting schedules are rejected, current production schedules remain conflict-free, and no QA data remains.' where version='2.0.2';
update public.training_app_versions set initial_problem='Generated Calendar/Completion links used legacy routes, public verification disclosed Badge/ID, and class lifecycle/privacy safeguards needed strengthening.',fix_summary='Corrected direct routes, removed public Badge/ID display, and strengthened finalization, scheduling, token, permission, email, and record integrity controls.',verification_summary='Recorded verification: Public certificate verification no longer discloses Badge # / ID #; the identifier remains retained in internal attendee records. Revalidated Attendance and Completion production endpoints and isolated the remaining legacy Completion compressed-wrapper cleanup as a frontend deployment item.' where version='2.0.1';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: training operations needed formal lifecycle controls, longitudinal attendee/agency history, readiness data, and public certificate verification.',fix_summary='Added class states, Start/Close controls, closed-before-finalization rules, persistent attendee identity, duplicate protection, agency history, trainer readiness, and verification.',verification_summary='Recorded verification: Added public certificate verification by certificate number or public certificate ID.' where version='2.0.0';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: attendee identification needed persistent Badge/ID records and releases needed formal version tracking.',fix_summary='Added Badge/ID to registration, rosters, historical records, print/CSV output, and dated application version history.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.6.0';
update public.training_app_versions set initial_problem='The Agency Portal lacked parity across the four training types, and configuration-fetch/Base64 wrappers caused Unable to Fetch / atob errors.',fix_summary='Added Portal training-type/tool/duration parity, removed the brittle wrappers, clarified agency trainer terminology, and renamed the attendance action Generate Class.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.5.0';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: staff needed audited request corrections, Teams links, certificate-email controls, and clearer manual illustrations.',fix_summary='Added administrator corrections with before/after audit, Teams links on requests and trainer output, certificate email/resend controls, and scalable manual references.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.4.0';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: class signup, check-in, rosters, certificates, completion, and past-class records were needed.',fix_summary='Introduced secure attendance links/QR codes, attendee registration/check-in, certificates, completion finalization, and searchable historical class records.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.3.0';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: the course catalog and request validation needed the complete four-course model and tool-based durations.',fix_summary='Added Basic, Train the Trainer, Refresher, and Advanced courses, tool selection, duration calculations, and single-choice validation.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.2.0';
update public.training_app_versions set initial_problem='Enhancement need inferred from the recorded changes: agency intake needed automatic directory creation, agency trainer contacts, resource selection, and revised training choices.',fix_summary='Expanded request intake, agency auto-add, trainer contact capture, resource fields, Train the Trainer, single-choice selection, and Computer with Wi-Fi. Removed Training Objectives.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.1.0';
update public.training_app_versions set initial_problem='Initial application baseline; no earlier production defect is documented.',fix_summary='Established the authenticated administration shell, public training-request intake, and agency/request directory workflow.',verification_summary='Separate test results were not recorded for this release. See the original release summary for any deployment qualification details.' where version='1.0.0';
commit;
